#define GAMMA   1.6
#define gamma(X)  pow(X, GAMMA)
#define degamma(X)  pow(X, 1./GAMMA)

// https://www.shadertoy.com/view/clB3zc
#define sfractN(x,w)   min( fract(x)/(1.-(w)), fract(-x)/(w) )
#define smodN(x,n,w)  (sfractN((x)/(n),w)*(n))
#define sfloorN(x,w)   max( floor(x), x - sfractN(x,w) )

float nonzero(float x, float minval) {
  return x >= 0. ? x+exp(-x)*minval : x-exp(x)*minval;
}

float nonzero(float x) {
  return nonzero(x, 1.);
}

float powX(float x, float f) {
  return x > 0. ? pow(x, f) : x < 0. ? -pow(-x, f) : 0.;
}

mat2 rotate2d(float a) {
  return mat2(cos(a), -sin(a), sin(a), cos(a));
}

float calc(in vec2 fragCoord, float size, float angle, float kx, float ky, vec2 offset) {
  vec2 stretch = fragCoord - iResolution.xy * 1.5 / 2.0 * sin(iTime/vec2(11.,19.));
  //float r = distance(vec2(0), fragCoord.xy) / iResolution.x * 4.;
  //float rr = 1.+sin(r*6.*(sin(iTime*0.04)/3.))/6.*powX(sin(iTime/3.),14.)*0.5;
  vec2 p = fragCoord.xy * rotate2d(angle + kx*stretch.x - ky*stretch.y);// * rr;
  vec2 pmod = smodN(p + offset, size * 2.0, 1./size);
  return max(pmod.x, pmod.y)/size/2.;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  float size = iResolution.x / (25.0 + powX(sin(iTime/5.5),9.)*10.);
  float angle = iTime / 10.0;
  float kx = sin(iTime/1.)/nonzero(iResolution.x*1.3*(1.-powX(sin(iTime/15.),5.)), 0.01);
  float ky = powX(sin(iTime/1.4),3.)/nonzero(iResolution.x*1.3*(1.-powX(sin(iTime/22.),7.)), 0.01);
  vec2 offset = iResolution.xy * cos(iTime/27.) * vec2(cos(iTime/15.), -sin(iTime/11.));
  vec2 offsetC = iResolution.xy * sin(iTime/37.) * vec2(sin(iTime/31.), cos(iTime/25.)) / 5.;
  fragCoord = fragCoord.xy - iResolution.xy / 2.0 + offsetC;
  float k = calc(fragCoord, size, angle, kx, ky, offset);
  //fragColor = vec4(vec3(gamma(k)), 1.0);
  //fragColor = vec4(vec3(degamma(k)), 1.0);
  fragColor = vec4(vec3(k), 1.0);
}
